"use client";
// @zeus-internal
import { Checkbox } from "../../../../lib/checkbox";
export function ContextCheckbox({checked,onChange,label,ariaLabel}:{checked:boolean;onChange:()=>void;label:string;ariaLabel:string}){return <Checkbox checked={checked} onCheckedChange={onChange} label={label} aria-label={ariaLabel} className="art:min-h-11 art:text-xs art:[&_button]:relative art:[&_button]:after:absolute art:[&_button]:after:-inset-3"/>;}

// @zeus-internal
export type Source = {
    id: string;
    title: string;
    content: string;
    type: "document" | "link" | "note";
    included: boolean;
    context?: string;
};
export const INITIAL_SOURCES: Source[] = [
    {
        "id": "0",
        "title": "Brand voice & writing guidelines",
        "content": "Write like a helpful teammate. Lead with the answer, use plain language, and keep interface labels short. Avoid jargon and explain the next step clearly.\n\nOur voice is thoughtful, direct, and warm. Prefer specific examples over broad promises.",
        "type": "document",
        "included": true
    },
    {
        "id": "1",
        "title": "Product overview",
        "content": "Workspace helps small teams organize projects and shared knowledge. Our customers are designers, engineers, and independent studios.\n\nFocus on practical workflows, clear ownership, and making useful information easy to find.",
        "type": "note",
        "included": true
    },
    {
        "id": "2",
        "title": "Customer help center",
        "content": "https://example.com/help",
        "type": "link",
        "context": "Reference link for customer-facing help articles. Verify the relevant article before using it as an answer source.",
        "included": true
    },
    {
        "id": "3",
        "title": "Autumn launch brief",
        "content": "Launch objective: introduce the new team workspace.\n\nAudience: existing customers and small creative teams.\n\nDeliverables: a product walkthrough, an announcement, and a concise getting-started guide.",
        "type": "document",
        "included": false
    },
    {
        "id": "4",
        "title": "Support response principles",
        "content": "Acknowledge the question, give the shortest complete answer, and include a useful next step. Never invent product capabilities or promise a release date. If the answer is uncertain, say what needs to be checked.",
        "type": "note",
        "included": true
    }
];

"use client";
// @zeus-internal
import { Dialog, DialogBackdrop, DialogPanel, DialogTitle, Description } from "../../../../lib/headless";
import { MotionConfig, motion, useReducedMotion } from "motion/react";
import { FileText, Upload, X, Trash2, Database } from "lucide-react";
import { useId, useState } from "react";
import { ArtemisButton } from "../../../../foundations/button";
import { ArtemisTextField } from "../../../../foundations/text-field";
import { ArtemisSegmentedTabs } from "../../../../foundations/segmented-tabs";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL } from "../../../../lib/ease";
import type { Source } from "./data";
type Props = {
    mode: Source["type"] | null;
    source: Source | null;
    onClose: () => void;
    onSave: (source: Source) => void;
    onDelete: (id: string) => void;
};
export function SourceDialog(props: Props) {
    const reduce = useReducedMotion();
    const open = props.mode !== null || props.source !== null;
    return <>{open ? <Dialog static open onClose={props.onClose} className="art:relative art:z-[100]">
    <MotionConfig transition={reduce ? { duration: 0 } : { duration: 0.15, ease: ARTEMIS_EASE_OUT }}>
      <DialogBackdrop as={motion.div} className="art:fixed art:inset-0 art:bg-foreground/10 art:backdrop-blur-sm" aria-hidden="true" initial={reduce ? false : { opacity: 0 }} animate={{ opacity: 1, transition: reduce ? { duration: 0 } : { duration: 0.2, ease: ARTEMIS_EASE_OUT } }} exit={{ opacity: 0 }}/>
      <div className="art:fixed art:inset-4 art:z-[101] art:overflow-x-hidden art:overflow-y-auto art:inset-y-6 art:@min-[640px]/artemis:inset-y-12 art:[&>div]:items-start">
        <div className="art:flex art:min-h-full art:items-center art:justify-center">
          <DialogPanel as={motion.div} className="art:w-full art:overflow-y-auto art:border art:border-border art:bg-background art:text-foreground art:will-change-transform art:max-h-[calc(100dvh-3rem)] art:max-w-2xl art:rounded-2xl art:p-5 art:@min-[640px]/artemis:max-h-[calc(100dvh-6rem)] art:@min-[640px]/artemis:p-7" initial={reduce ? false : { opacity: 0, y: 8, scale: 0.96 }} animate={{ opacity: 1, y: 0, scale: 1, transition: reduce ? { duration: 0 } : ARTEMIS_SPRING_PANEL }} exit={{ opacity: 0, y: 6, scale: 0.96 }}>
            <Editor {...props}/>
          </DialogPanel>
        </div>
      </div>
    </MotionConfig>
  </Dialog> : null}</>;
}
function Editor({ mode, source, onClose, onSave, onDelete }: Props) {
    const [type, setType] = useState<Source["type"]>(source?.type ?? mode ?? "note");
    const [title, setTitle] = useState(source?.title ?? " ");
    const [content, setContent] = useState(source?.type === "link" ? source.context ?? " " : source?.content ?? " ");
    const [url, setUrl] = useState(source?.type === "link" ? source.content : "");
    const [error, setError] = useState(" ");
    const hint = useId();
    const [confirmRemove, setConfirmRemove] = useState(false);
    return <>
    <div className="art:mb-5 art:flex art:shrink-0 art:items-start art:justify-between art:gap-4">
      <div><DialogTitle className="art:text-xl art:font-medium">{source ? "Source details" : "Add knowledge"}</DialogTitle><Description className="art:mt-2 art:text-sm art:text-muted-foreground">Give your assistant useful context to work with.</Description></div>
      <ArtemisButton variant="ghost" size="icon" className="art:size-9" aria-label="Close source editor" onClick={onClose}><X size={18}/></ArtemisButton>
    </div>
    <form noValidate onSubmit={event => {
            event.preventDefault();
            if (!title.trim()) {
                setError("Give this source a title.");
                return;
            }
            if (type === "link") {
                try {
                    const parsed = new URL(url);
                    if (!/^https?:$/.test(parsed.protocol))
                        throw new Error();
                }
                catch {
                    setError("Enter a complete http or https URL.");
                    return;
                }
            }
            else if (!content.trim()) {
                setError("Add some content before saving this source.");
                return;
            }
            onSave({ id: source?.id ?? `source-${Date.now()}`, type, title: title.trim(), content: type === "link" ? url.trim() : content, context: type === "link" ? content : undefined, included: source?.included ?? true });
        }}>
      <fieldset className="art:space-y-5">
        {!source ? <div className="art:shrink-0"><ArtemisSegmentedTabs items={["note", "link", "document"].map(value => ({ value, label: value }))} value={type} onValueChange={value => { setType(value as Source["type"]); setError(" "); }} ariaLabel="Source type" layout="position" roving={{ homeEnd: false }} listClassName="art:inline-flex art:items-center art:rounded-full art:gap-2 art:bg-muted art:p-0" buttonClassName="art:h-9 art:rounded-full art:px-4 art:text-xs art:capitalize art:focus-visible:ring-2 art:focus-visible:ring-ring"/></div> : null}
        <div className="art:space-y-5 art:px-1 art:pb-1">
          {type === "document" ? <div className="art:rounded-2xl art:border art:border-dashed art:border-border art:p-5">
            <div className="art:flex art:items-center art:gap-3"><span className="art:flex art:size-10 art:items-center art:justify-center art:rounded-full art:border art:border-border"><FileText size={18}/></span><div><p className="art:text-sm art:font-medium">Import a text document</p><p className="art:mt-1 art:text-xs art:text-muted-foreground">Plain text or Markdown · up to 1 MB</p></div></div>
            <label className="art:relative art:mt-4 art:inline-flex art:h-9 art:cursor-pointer art:items-center art:gap-2 art:rounded-full art:border art:border-border art:px-4 art:text-xs art:focus-within:ring-2 art:focus-within:ring-ring"><Upload size={14}/>Choose file<input accept=".txt,.md,text/plain,text/markdown" aria-label="Import text document" className="art:absolute art:inset-0 art:w-full art:cursor-pointer art:opacity-0" type="file" onChange={async (event) => {
                const input = event.currentTarget;
                const file = input.files?.[0];
                input.value = "";
                if (!file)
                    return;
                if (!/\.(txt|md)$/i.test(file.name) || file.size > 1024 * 1024) {
                    setError("Choose a .txt or .md file smaller than 1 MB.");
                    return;
                }
                setTitle(file.name);
                setContent(await file.text());
                setError(" ");
            }}/></label>
          </div> : null}
          <ArtemisTextField label="Title" className="art:w-full" maxLength={120} placeholder="e.g. Customer support playbook" value={title} onChange={event => setTitle(event.target.value)}/>
          {type === "link" ? <div><ArtemisTextField label="Source URL" className="art:w-full" aria-describedby={hint} placeholder="https://example.com/help" type="url" value={url} onChange={event => setUrl(event.target.value)}/><p id={hint} className="art:mt-2 art:text-xs art:text-muted-foreground">Links are saved as references. Page content is not fetched in this preview.</p></div> : null}
          <label className="art:block art:text-sm art:font-medium">{type === "link" ? "Context for this link" : "Source content"}<textarea rows={7} placeholder="Add the details your assistant should know…" className="art:mt-2 art:w-full art:resize-y art:rounded-2xl art:border art:border-border art:bg-background art:px-4 art:py-3 art:text-sm art:font-normal art:leading-relaxed art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring" value={content} onChange={event => setContent(event.target.value)}/></label>
        </div>
      </fieldset>
      <p role="alert" className="art:mt-4 art:text-sm art:text-destructive">{error}</p>
      {confirmRemove && source ? <div className="art:mt-5 art:rounded-xl art:border art:border-border art:p-4"><p className="art:text-sm">Remove this source from the knowledge base?</p><div className="art:mt-3 art:flex art:gap-2"><ArtemisButton variant="ghost" className="art:h-9 art:text-xs" onClick={() => setConfirmRemove(false)}>Keep source</ArtemisButton><ArtemisButton variant="tertiary" className="art:h-9 art:text-xs" onClick={() => onDelete(source.id)}>Remove source</ArtemisButton></div></div> : null}
      <footer className="art:mt-6 art:flex art:shrink-0 art:flex-wrap art:items-center art:justify-between art:gap-3 art:border-t art:border-border art:pt-5">
        {source ? <ArtemisButton variant="ghost" className="art:h-9 art:text-xs" onClick={() => setConfirmRemove(true)}><Trash2 size={14}/>Remove</ArtemisButton> : <span className="art:text-xs art:text-muted-foreground">Review your source before adding it.</span>}
        <ArtemisButton type="submit" className="art:h-9 art:text-xs">{source ? "Save changes" : "Add source"}</ArtemisButton>
      </footer>
    </form>
  </>;
}
export function renderEmptySources({ empty, onClear, onAdd }: {
    empty: boolean;
    onClear: () => void;
    onAdd: () => void;
}) {
    return <div className="art:rounded-2xl art:border art:border-dashed art:border-border art:px-5 art:py-12 art:text-center"><Database size={25} className="art:mx-auto art:text-muted-foreground"/><h3 className="art:mt-4 art:text-xl art:font-medium">{empty ? "A smarter assistant starts here" : "No matching sources"}</h3><p className="art:mt-2 art:text-sm art:text-muted-foreground">{empty ? "Add a note, a document, or a reference link." : "Try another search or choose a different source type."}</p><ArtemisButton variant="tertiary" className="art:mt-5 art:h-9 art:text-xs" onClick={empty ? onAdd : onClear}>{empty ? "Add your first source" : "Clear filters"}</ArtemisButton></div>;
}

"use client";
// @zeus-internal
import { FileText, Earth, StickyNote } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import { ARTEMIS_SPRING_PRESS } from "../../../../lib/ease";
import { ContextCheckbox } from "./context-checkbox";
import type { Source } from "./data";
export function SourceRow({ source, onOpen, onToggle }: {
    source: Source;
    onOpen: (source: Source) => void;
    onToggle: (id: string) => void;
}) {
    const reduce = useReducedMotion();
    return (<div className="art:flex art:flex-wrap art:items-center art:gap-4 art:py-4">
                  <span className="art:flex art:size-10 art:shrink-0 art:items-center art:justify-center art:rounded-full art:border art:border-border">
                    {source.type === "document" ? <FileText size={18}/> : source.type === "link" ? <Earth size={18}/> : <StickyNote size={18}/>}
                  </span>
                  <div className="art:min-w-0 art:flex-1">
                    <motion.button whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => onOpen(source)} type="button" className="art:inline-flex art:items-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:hover:text-foreground art:gap-2 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:max-w-full art:justify-start art:px-0 art:text-left art:text-sm art:text-foreground art:hover:bg-transparent art:focus-visible:ring-2 art:focus-visible:ring-ring art:h-9 art:rounded-full" tabIndex={0}>
                      <span className="art:truncate">
                        {source.title}
                      </span>
                      <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:shrink-0 art:text-muted-foreground" aria-hidden="true">
                        <path d="M7 7h10v10"/>
                        <path d="M7 17 17 7"/>
                      </svg>
                    </motion.button>
                    <p className="art:line-clamp-1 art:text-xs art:text-muted-foreground">
                      {source.content}
                    </p>
                    <p className="art:mt-2 art:text-xs art:text-muted-foreground">
                      {source.type === "link" ? "Reference link" : `${source.type === "document" ? "Document" : "Note"} \u00B7 ${source.content.length} characters`}
                    </p>
                  </div>
                  <div className="art:ml-14 art:@min-[640px]/artemis:ml-0">
                    <ContextCheckbox checked={source.included} onChange={() => onToggle(source.id)} label="Use in AI" ariaLabel={`Use ${source.title} in assistant context`}/>
                  </div>
                </div>);
}

"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "./ease";
export function ArtemisCheckMark({ selected, mixed = false }: { selected: boolean; mixed?: boolean }) {
  const reduce = useReducedMotion();
  return <AnimatePresence initial={false}>{selected && <motion.svg key={mixed ? "mixed" : "check"} width={12} height={12} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" initial={reduce ? false : { opacity: 0, scale: 0.5 }} animate={{ opacity: 1, scale: 1 }} exit={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.5, filter: "blur(4px)" }} transition={{ duration: reduce ? 0 : 0.16, ease: ARTEMIS_EASE_OUT }}><motion.path d={mixed ? "M6 12H18" : "M5 13L9 17L19 7"} pathLength={1} initial={reduce ? false : { pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ duration: reduce ? 0 : mixed ? 0.2 : 0.3, delay: reduce ? 0 : 0.04, ease: ARTEMIS_EASE_OUT }}/></motion.svg>}</AnimatePresence>;
}

"use client";
// @zeus-internal
import { useId } from "react";
import { ArtemisPressButton } from "./press-button";
import { ArtemisCheckMark } from "./check-mark";
import { artemisCx } from "./utils";
export interface CheckboxProps { checked: boolean; onCheckedChange: (checked: boolean) => void; disabled?: boolean; indeterminate?: boolean; label?: string; description?: string; className?: string; id?: string; "aria-label"?: string; "aria-describedby"?: string; }
export function Checkbox({ checked, onCheckedChange, disabled, indeterminate, label, description, className, id: givenId, "aria-label": ariaLabel, "aria-describedby": describedBy }: CheckboxProps) {
  const unique = useId(), id = givenId ?? unique;
  const selected = checked || !!indeterminate;
  const descriptionId = description ? `${id}-description` : undefined;
  return <label htmlFor={id} className={artemisCx("art:inline-flex art:gap-3", description ? "art:items-start" : "art:items-center", disabled ? "art:cursor-not-allowed" : "art:cursor-pointer", className)}>
    <ArtemisPressButton hoverScale={null} pressScale={0.92} id={id} type="button" role="checkbox" aria-checked={indeterminate ? "mixed" : checked} aria-label={ariaLabel} aria-labelledby={!ariaLabel && label ? `${id}-label` : undefined} aria-describedby={[describedBy, descriptionId].filter(Boolean).join(" ") || undefined} data-state={indeterminate ? "indeterminate" : checked ? "checked" : "unchecked"} disabled={disabled} onClick={() => onCheckedChange(!checked)} className={artemisCx("art:inline-flex art:h-5 art:w-5 art:shrink-0 art:items-center art:justify-center art:rounded-md art:border-2 art:outline-none art:transition-colors art:duration-200 art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:disabled:cursor-not-allowed art:disabled:opacity-60", selected ? "art:border-primary art:bg-primary art:text-primary-foreground" : "art:border-muted-foreground/50 art:bg-background art:hover:border-muted-foreground")}><ArtemisCheckMark selected={selected} mixed={indeterminate}/></ArtemisPressButton>
    {(label || description) && <span className="art:flex art:min-w-0 art:flex-col art:gap-0.5"><span id={`${id}-label`} className={artemisCx("art:text-sm art:text-foreground",description && "art:leading-4")}>{label}</span>{description && <span id={descriptionId} className="art:text-xs art:text-muted-foreground">{description}</span>}</span>}
  </label>;
}

export { Checkbox as ArtemisCheckbox };

"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, useState, type InputHTMLAttributes, type ReactNode, type Ref } from "react";
import { ArtemisValidationFrame } from "./validation-frame";
import { artemisCx } from "./utils";
export interface ArtemisFormFieldProps extends Omit<InputHTMLAttributes<HTMLInputElement>, "className"> {
    label?: string;
    className?: string;
    inputClassName?: string;
    error?: string | boolean;
    icon?: ReactNode;
    trailing?: ReactNode;
    focusBorder?: string;
    fullWidth?: boolean;
    fieldClassName?: string;
    labelClassName?: string;
    inputRef?: Ref<HTMLInputElement>;
    leadingContent?: ReactNode;
    trailingContent?: ReactNode;
}
export function ArtemisFormField({ label, className, inputClassName, error, icon, trailing, focusBorder = "art:border-muted-foreground/40", fullWidth = true, fieldClassName, labelClassName, inputRef, leadingContent, trailingContent, id: givenId, disabled, onFocus, onBlur, ...input }: ArtemisFormFieldProps) {
    const unique = useId(), id = givenId ?? unique, reduce = useReducedMotion(), invalid = !!error, message = typeof error === "string" ? error : undefined;
    const [focused, setFocused] = useState(false);
    return <div className={artemisCx("art:flex art:flex-col art:gap-1.5", fullWidth && "art:w-full", className)}>
  {label && <label htmlFor={id} className={artemisCx("art:px-1 art:text-sm art:font-medium art:text-foreground", labelClassName)}>{label}</label>}
  <ArtemisValidationFrame error={invalid} focused={focused} focusBorder={focusBorder} className={artemisCx(disabled && "art:opacity-60",fieldClassName)}>
   {leadingContent}
   {icon && <span className="art:pointer-events-none art:absolute art:left-3 art:top-1/2 art:flex art:-translate-y-1/2 art:items-center art:text-muted-foreground art:[&_svg]:h-4 art:[&_svg]:w-4">{icon}</span>}
   <input ref={inputRef} {...input} id={id} disabled={disabled} onFocus={event => { setFocused(true); onFocus?.(event); }} onBlur={event => { setFocused(false); onBlur?.(event); }} aria-invalid={invalid || input["aria-invalid"] || undefined} aria-describedby={[input['aria-describedby'], message ? `${id}-error` : undefined].filter(Boolean).join(' ') || undefined} className={artemisCx("art:peer art:h-full art:w-full art:bg-transparent art:text-sm art:leading-6 art:text-foreground art:caret-foreground art:outline-none art:placeholder:text-muted-foreground/60 art:pl-3.5 art:pr-3.5", icon && "art:pl-10", disabled && "art:cursor-not-allowed", inputClassName)}/>
   {trailingContent}
   {trailing && <span className="art:absolute art:right-0 art:top-0 art:flex art:h-full art:items-center art:text-muted-foreground art:[&_button]:grid art:[&_button]:size-10 art:[&_button]:place-items-center art:[&_svg]:h-4 art:[&_svg]:w-4">{trailing}</span>}
  </ArtemisValidationFrame>
  <div className="art:contents"><AnimatePresence initial={false}>{message && <motion.p key="error" id={`${id}-error`} role="alert" className="art:px-1 art:text-xs art:text-destructive" initial={reduce ? { opacity: 0 } : { opacity: 0, y: -4, filter: "blur(4px)" }} animate={{ opacity: 1, y: 0, filter: "blur(0px)" }} exit={reduce ? { opacity: 0 } : { opacity: 0, y: -4, filter: "blur(4px)" }} transition={{ duration: .2 }}>{message}</motion.p>}</AnimatePresence></div>
 </div>;
}

"use client";
// @zeus-internal
import { motion, useReducedMotion, type HTMLMotionProps } from "motion/react";
import { ARTEMIS_SPRING_PRESS } from "./ease";
export function ArtemisPressButton({ pressScale = 0.99, hoverScale = 1.01, ...props }: HTMLMotionProps<"button"> & { pressScale?: number | null; hoverScale?: number | null }) {
  const still = useReducedMotion() === true;
  return <motion.button {...props} whileHover={still || hoverScale === null || props.disabled ? undefined : { scale: hoverScale }} whileTap={still || pressScale === null || props.disabled ? undefined : { scale: pressScale }} transition={ARTEMIS_SPRING_PRESS}/>;
}

"use client";
// @zeus-internal
import { animate, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState, type HTMLAttributes } from "react";
export interface ArtemisValidationFrameProps extends HTMLAttributes<HTMLDivElement> {
    error?: boolean;
    focused?: boolean;
    focusBorder?: string;
    finishShakeOnClear?: boolean;
}
export function ArtemisValidationFrame({ error = false, focused: controlled, focusBorder = "art:border-foreground/60", finishShakeOnClear = true, className = "", children, onFocus, onBlur, ...props }: ArtemisValidationFrameProps) {
    const [focus, setFocus] = useState(false);
    const ref = useRef<HTMLDivElement>(null);
    const reduce = useReducedMotion();
    const playbackRef = useRef<{
        stop: () => void;
    } | null>(null);
    useEffect(() => () => playbackRef.current?.stop(), []);
    const focused = controlled ?? focus;
    useEffect(() => {
        const element = ref.current;
        if (!element || !error || reduce) {
            if (element && (reduce || !finishShakeOnClear)) {
                playbackRef.current?.stop();
                playbackRef.current = null;
                element.style.transform = "none";
                element.style.translate = "none";
            }
            return;
        }
        playbackRef.current?.stop();
        const playback = animate(element, { x: [0, -6, 6, -4, 4, -2, 0] }, { duration: 0.45 });
        playbackRef.current = playback;
        return () => { if (!finishShakeOnClear) {
            playback.stop();
            if (playbackRef.current === playback)
                playbackRef.current = null;
        } };
    }, [error, reduce, finishShakeOnClear]);
    const border = error ? "art:border-destructive" : focused ? focusBorder : "art:border-border";
    return <div {...props} ref={ref} data-state={error ? "error" : focused ? "focused" : "idle"} className={`art:relative art:h-10 art:overflow-hidden art:rounded-full art:border art:bg-background art:transition-colors art:duration-200 ${border} ${className}`} onFocus={event => { setFocus(true); onFocus?.(event); }} onBlur={event => { if (!event.currentTarget.contains(event.relatedTarget))
        setFocus(false); onBlur?.(event); }}>{children}</div>;
}
